window.LD=window.LD||{};window.LD["headlines"]={"1":[{"id":"e1","day":1,"season":1,"sday":1,"kind":"season_start","imp":5,"text":"Season 1 begins: A Quiet Year. Nothing much. Which, for adventurers, is its own kind of trouble.","heroes":[],"parties":[]},{"id":"e21","day":1,"season":1,"sday":1,"kind":"weather","imp":2,"text":"Thunder over the west. Chloe counts the seconds between flash and boom, and does not like the number.","heroes":["h17"],"parties":[],"loc":"hollowood"},{"id":"e22","day":1,"season":1,"sday":1,"kind":"weather","imp":2,"text":"A storm breaks across the east. Mark spends it under a cart, sharing the space with a goat.","heroes":["h18"],"parties":[],"loc":"saltmarrow"},{"id":"e24","day":1,"season":1,"sday":1,"kind":"legend","imp":4,"text":"Old Marrow, the Last of the Ninefold, walks into The Pickaxe & Pint, buys the house a round, tells one story nobody will ever forget, and is gone before the second round.","heroes":["h2"],"parties":[],"loc":"veldrock","legend":"Old Marrow"},{"id":"e25","day":1,"season":1,"sday":1,"kind":"odd_job","imp":3,"text":"Mother Grall watched Ryan spend a whole day fishing a dropped ring out of the well behind The Pickaxe & Pint without one complaint, then disappeared into a back room and came out with a silver button with a story. \"My father's. Take it.\"","heroes":["h15"],"parties":[],"loc":"veldrock"},{"id":"e26","day":1,"season":1,"sday":1,"kind":"cart","imp":2,"text":"A cheese-seller hires Sam to see a load of salt fish safely to the quarry. Safely is how it goes. 12 silver.","heroes":["h1"],"parties":[],"loc":"frosthold"},{"id":"e27","day":1,"season":1,"sday":1,"kind":"odd_job","imp":2,"text":"Waiting on company that hasn't come, Natasha keeps busy throwing out a drunk who turned out to be the mayor's cousin for Madame Ostrava. It pays 10 silver.","heroes":["h11"],"parties":[],"loc":"ironhaven"},{"id":"e28","day":1,"season":1,"sday":1,"kind":"odd_job","imp":2,"text":"The adventuring life, Ironhaven edition: Echo, working the bellows at the forge, for Bertil Hammerhand. 9 silver.","heroes":["h6"],"parties":[],"loc":"ironhaven"},{"id":"e29","day":1,"season":1,"sday":1,"kind":"night","imp":2,"text":"A carter with a broken wheel on the road to Frosthold pays for Matt McF's help in gossip: the deep rooms of Thornmere Ruins are open again.","heroes":["h12"],"parties":[],"loc":"ironhaven"},{"id":"e30","day":1,"season":1,"sday":1,"kind":"fight","imp":3,"text":"First blood for Yomna: Yomna handles a Wolf on the cart road to the quarry.","heroes":["h10"],"parties":[],"loc":"kingsroad"},{"id":"e31","day":1,"season":1,"sday":1,"kind":"cart","imp":3,"text":"Yomna stands between the crates that tick and trouble on the road to the quarry, and trouble loses. A carter called Hob pays 15 silver and tells everyone in Ironhaven.","heroes":["h10"],"parties":[],"loc":"ironhaven"},{"id":"e32","day":1,"season":1,"sday":1,"kind":"cart","imp":2,"text":"There and back to the orchard estates with a widow with a wagon and the cheeses. Ankit earns 12 silver mostly for looking dangerous at crossroads.","heroes":["h14"],"parties":[],"loc":"ironhaven"},{"id":"e33","day":1,"season":1,"sday":1,"kind":"cart","imp":2,"text":"Escort work, of a sort: Claire walks a nervous young carter and a cart of wedding cakes to the orchard estates and back by supper. 12 silver, no blood.","heroes":["h9"],"parties":[],"loc":"thornwall"},{"id":"e34","day":1,"season":1,"sday":1,"kind":"fight","imp":3,"text":"First blood for Mikolaj: Mikolaj defeats a Wolf on the cart road to the charcoal-burners' camp. Loot: 1 pelt.","heroes":["h16"],"parties":[],"loc":"kingsroad"},{"id":"e35","day":1,"season":1,"sday":1,"kind":"cart","imp":3,"text":"It was meant to be an easy job. Halfway to the charcoal-burners' camp it isn't, and Mikolaj earns every one of the 15 silver a tinker with a squeaking wheel pays out at the end.","heroes":["h16"],"parties":[],"loc":"ironhaven"},{"id":"e36","day":1,"season":1,"sday":1,"kind":"fight","imp":3,"text":"First blood for Garrett: Garrett handles a Wolf on the cart road to the market crossroads. Loot: 1 pelt.","heroes":["h4"],"parties":[],"loc":"greenwood"},{"id":"e37","day":1,"season":1,"sday":1,"kind":"cart","imp":3,"text":"A travelling dentist's cart of pigs gets jumped on the way to the market crossroads, and Garrett is the reason it gets there anyway. 14 silver, and the story is all over Thornwall by dark.","heroes":["h4"],"parties":[],"loc":"thornwall"},{"id":"e38","day":1,"season":1,"sday":1,"kind":"cooking","imp":2,"text":"The special at The Sagging Beam this week is Goblin Goulash. Garrett orders it twice and sends compliments to Old Hesk.","heroes":["h4"],"parties":[],"loc":"thornwall"},{"id":"e39","day":1,"season":1,"sday":1,"kind":"odd_job","imp":2,"text":"A quiet day for Kev, mostly minding a baby while its mother sold eggs for a family of seven in a house built for two. The pay is 10 silver and far too much advice.","heroes":["h2"],"parties":[],"loc":"veldrock"},{"id":"e40","day":1,"season":1,"sday":1,"kind":"cart","imp":2,"text":"Robert keeps a hand near his weapon all the way to the mill and never needs it. A boy driving his father's cart for the first time calls it money well spent: 11 silver.","heroes":["h7"],"parties":[],"loc":"thornwall"},{"id":"e41","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Veronika and Claire shake on it at The Sagging Beam: they are now Copper Whiskers. (Wary, by the look of them.)","heroes":["h13","h9"],"parties":["p1"],"loc":"thornwall"},{"id":"e42","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Echo and Natasha shake on it at The Gilded Flagon: they are now The Verdant Sigil. (Honorable, by the look of them.)","heroes":["h6","h11"],"parties":["p2"],"loc":"ironhaven"},{"id":"e43","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Yomna and Mikolaj shake on it at The Gilded Flagon: they are now The Royal Vigil. (Honorable, by the look of them.)","heroes":["h10","h16"],"parties":["p3"],"loc":"ironhaven"},{"id":"e45","day":1,"season":1,"sday":1,"kind":"party_join","imp":3,"text":"Robert joins Copper Whiskers over drinks in Thornwall. That makes 3.","heroes":["h7","h13","h9"],"parties":["p1"],"loc":"thornwall"},{"id":"e47","day":1,"season":1,"sday":1,"kind":"companion","imp":2,"text":"On the road to Frosthold, Matt McF falls in with Mother Agnes, a midwife on her rounds. They agree to walk together for a few days. Safety in numbers, even small numbers.","heroes":["h12"],"parties":[],"loc":"ironhaven"},{"id":"e48","day":1,"season":1,"sday":1,"kind":"companion","imp":2,"text":"Sister Rue, a nun who swears beautifully, asks Griffin which way to Thornwall. It turns out to be Griffin's way too. Company for a few days, then.","heroes":["h5"],"parties":[],"loc":"ironhaven"},{"id":"e49","day":1,"season":1,"sday":1,"kind":"companion","imp":2,"text":"At a milestone outside Frosthold, Spencer meets Teodor, a minstrel who knows half of every song. By the next milestone they're travelling together.","heroes":["h8"],"parties":[],"loc":"veldrock"},{"id":"e50","day":1,"season":1,"sday":1,"kind":"campfire","imp":2,"text":"Echo offers Natasha the dry side of the tent. Natasha accepts, suspiciously.","heroes":["h6","h11"],"parties":["p2"],"loc":"ironhaven"},{"id":"e52","day":1,"season":1,"sday":1,"kind":"first_night","imp":2,"text":"First night in Frosthold: Varun bought a Wool Hood from Ragna in Frosthold for 6s. Asked what he wanted, he said: to slay the dragon of Emberdeep.","heroes":["h3"],"parties":[],"loc":"frosthold"}],"2":[{"id":"e56","day":2,"season":1,"sday":2,"kind":"odd_job","imp":3,"text":"Odd job, odd ending: Garrett is helping dig a grave nobody wants to talk about for Sister Amberline and turns up a healing draught, long lost. Sister Amberline insisted Garrett keep it, and told the whole street why.","heroes":["h4"],"parties":[],"loc":"thornwall"},{"id":"e57","day":2,"season":1,"sday":2,"kind":"contract","imp":3,"text":"First job for Ryan: The guild in Veldrock hires Ryan to walk medicine for the temple to Frosthold. 32 silver each, if it all arrives.","heroes":["h15"],"parties":[],"loc":"veldrock"},{"id":"e58","day":2,"season":1,"sday":2,"kind":"odd_job","imp":2,"text":"No monsters today: Ankit is sorting a heap of scrap iron for Bertil Hammerhand, for 8 silver and a blessing of uncertain quality.","heroes":["h14"],"parties":[],"loc":"ironhaven"},{"id":"e59","day":2,"season":1,"sday":2,"kind":"contract","imp":3,"text":"First job for Sam: A man in Frosthold who doesn't give his name pays Sam to move somebody's very quiet cousin to Ironhaven. Half now, half on arrival, no questions.","heroes":["h1"],"parties":[],"loc":"frosthold"},{"id":"e60","day":2,"season":1,"sday":2,"kind":"party_join","imp":3,"text":"Griffin joins Copper Whiskers over drinks in Thornwall. That makes 4.","heroes":["h5","h13","h9","h7"],"parties":["p1"],"loc":"thornwall"},{"id":"e62","day":2,"season":1,"sday":2,"kind":"party_formed","imp":4,"text":"Chloe and Garrett shake on it at The Sagging Beam: they are now The Cobalt Storm. (Honorable, by the look of them.)","heroes":["h17","h4"],"parties":["p4"],"loc":"thornwall"},{"id":"e63","day":2,"season":1,"sday":2,"kind":"keepsake","imp":2,"text":"Ankit asks the tavern crowd whether anyone's been down the Collapsed Mine. Ankit doesn't mention the map.","heroes":["h14"],"parties":[],"loc":"ironhaven"},{"id":"e64","day":2,"season":1,"sday":2,"kind":"party_formed","imp":4,"text":"Varun and Matt McF shake on it at The Third Coat: they are now The Azure Stallions. (Honorable, by the look of them.)","heroes":["h3","h12"],"parties":["p5"],"loc":"frosthold"},{"id":"e65","day":2,"season":1,"sday":2,"kind":"journey","imp":2,"text":"Ryan and Spencer share the road to Frosthold. By the second milestone they've agreed on nothing, least of all what they'd do if they retired.","heroes":["h15","h8"],"parties":[]},{"id":"e66","day":2,"season":1,"sday":2,"kind":"journey","imp":2,"text":"On the way to Ironhaven, Varun catches up with Sam. The conversation turns to Varun's terrible singing and never recovers.","heroes":["h3","h1"],"parties":[]},{"id":"e67","day":2,"season":1,"sday":2,"kind":"companion","imp":2,"text":"A lone hero and Quill, a clerk walking off a broken heart, share a fire on the road to the Greenwood, and in the morning simply keep walking together.","heroes":["h19"],"parties":[],"loc":"ironhaven"},{"id":"e69","day":2,"season":1,"sday":2,"kind":"campfire","imp":2,"text":"Griffin catches Veronika humming and doesn't say anything. That's a start.","heroes":["h13","h5"],"parties":["p1"],"loc":"thornwall"}],"3":[{"id":"e72","day":3,"season":1,"sday":3,"kind":"legend","imp":4,"text":"Brother Toad, Keeper of the Long Road, blesses Ankit in Ironhaven. It feels like it might actually work.","heroes":["h14"],"parties":[],"loc":"ironhaven","legend":"Brother Toad"},{"id":"e73","day":3,"season":1,"sday":3,"kind":"town","imp":2,"text":"A stranger in Ironhaven sells Matt McF a treasure map for 11 silver. On closer inspection it is a map of Ironhaven. With an X on the tavern.","heroes":["h12"],"parties":[],"loc":"ironhaven"},{"id":"e74","day":3,"season":1,"sday":3,"kind":"contract","imp":2,"text":"Ryan walks medicine for the temple from Veldrock to Frosthold without incident and collects 32 silver each. Boring. Paid.","heroes":["h15"],"parties":[],"loc":"frosthold"},{"id":"e75","day":3,"season":1,"sday":3,"kind":"town","imp":3,"text":"A stray cat follows Ryan out of Frosthold and refuses to leave. Ryan names it Pharaoh, and Pharaoh is a member of the league now.","heroes":["h15"],"parties":[],"loc":"frosthold"},{"id":"e76","day":3,"season":1,"sday":3,"kind":"ambush","imp":3,"text":"First blood for Sam: on the road to Ironhaven, Sam dispatches a Wolf. Loot: 1 pelt.","heroes":["h1"],"parties":[],"loc":"kingsroad"},{"id":"e77","day":3,"season":1,"sday":3,"kind":"fight","imp":3,"text":"First blood for Spencer, who defeats a Wolf just outside Frosthold.","heroes":["h8"],"parties":[],"loc":"whitepeak"},{"id":"e78","day":3,"season":1,"sday":3,"kind":"small_hunt","imp":2,"text":"Spencer spends the day hunting wolves around the hen houses on behalf of Watchman Brynjar. It goes badly for the wolves. 13 silver.","heroes":["h8"],"parties":[],"loc":"frosthold"},{"id":"e79","day":3,"season":1,"sday":3,"kind":"contract","imp":3,"text":"First job for Ankit: the guild in Ironhaven hires him to walk barrels of ale to Carrbridge, at 23 silver each, if it all arrives.","heroes":["h14"],"parties":[],"loc":"ironhaven"},{"id":"e82","day":3,"season":1,"sday":3,"kind":"contract","imp":2,"text":"A quiet escort: barrels of ale, Ironhaven to Carrbridge, 23 each. The merchant tips extra for the conversation.","heroes":["h14"],"parties":[],"loc":"carrbridge"},{"id":"e83","day":3,"season":1,"sday":3,"kind":"ambush","imp":3,"text":"First blood for Veronika, Claire, Robert and Griffin: in the middle of the night, Copper Whiskers make short work of 3 Bandits at their camp on the road to Ironhaven. Veronika called out every flank before it turned, and Griffin spotted the tripwire before anyone stepped on it. \"Hit it until it stopped. Worked,\" says G","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"kingsroad"},{"id":"e84","day":3,"season":1,"sday":3,"kind":"ambush","imp":3,"text":"First blood for Chloe: The Cobalt Storm routs 2 Wolves on the road to the Greenwood, with Chloe everywhere at once. Garrett was thinking about the Ashveil Crypts the whole fight, and the map in his pack. \"Everyone all right? Everyone?\" says Garrett. Loot: 2 pelts, 2 fangs & claws.","heroes":["h17","h4"],"parties":["p4"],"loc":"greenwood"},{"id":"e85","day":3,"season":1,"sday":3,"kind":"party_join","imp":3,"text":"Christian joins The Verdant Sigil over drinks in Thornwall. That makes 3.","heroes":["h19","h6","h11"],"parties":["p2"],"loc":"thornwall"},{"id":"e86","day":3,"season":1,"sday":3,"kind":"meet","imp":2,"text":"Christian runs into Copper Whiskers on the road between Ironhaven and Thornwall. Stories are exchanged, most of them exaggerated.","heroes":["h19","h13","h9","h7","h5"],"parties":["p1"],"loc":"ironhaven"},{"id":"e87","day":3,"season":1,"sday":3,"kind":"journey","imp":2,"text":"The Azure Stallions and Sam fall in together on the road to Ironhaven and spend the miles arguing about old scars.","heroes":["h3","h12","h1"],"parties":["p5"]},{"id":"e88","day":3,"season":1,"sday":3,"kind":"journey","imp":2,"text":"Christian and The Verdant Sigil share the road to Thornwall. By the second milestone they've agreed on nothing, least of all a shortcut that turned out to be a longcut.","heroes":["h19","h6","h11","h19"],"parties":["p2"]},{"id":"e89","day":3,"season":1,"sday":3,"kind":"companion","imp":2,"text":"Mark picks up a travelling companion on the way to Ashfen: Wenna, a pedlar with a squeaky handcart. Neither of them says it, but it's nice not to walk alone.","heroes":["h18"],"parties":[],"loc":"saltmarrow"},{"id":"e90","day":3,"season":1,"sday":3,"kind":"companion","imp":2,"text":"Kev has company on the road to Ironhaven: Ines, a mapmaker who keeps getting lost, who talks enough for two.","heroes":["h2"],"parties":[],"loc":"veldrock"}],"4":[{"id":"e92","day":4,"season":1,"sday":4,"kind":"contract","imp":2,"text":"The guild clerks finally square their ledgers: an escort now counts as experience as well as silver, and Ankit and Ryan are credited for the roads already walked.","heroes":["h14","h15"],"parties":[]},{"id":"e94","day":4,"season":1,"sday":4,"kind":"contract","imp":4,"text":"Ironhaven's guards were waiting. Somebody talked. Sam is fined 30 silver and locked up while the magistrate decides how embarrassed to be.","heroes":["h1"],"parties":[],"loc":"ironhaven"},{"id":"e96","day":4,"season":1,"sday":4,"kind":"cart","imp":3,"text":"A newly married farmer's cart of crates that tick gets jumped on the way to the toll bridge, and Spencer is the reason it gets there anyway. 20 silver, and the story is all over Frosthold by dark.","heroes":["h8"],"parties":[],"loc":"frosthold"},{"id":"e97","day":4,"season":1,"sday":4,"kind":"contract","imp":2,"text":"A man in Frosthold who doesn't give his name pays Ryan to move a sealed chest that must not be opened to Ironhaven. Half now, half on arrival, no questions.","heroes":["h15"],"parties":[],"loc":"frosthold"},{"id":"e100","day":4,"season":1,"sday":4,"kind":"town_life","imp":2,"text":"The Carrbridge crier's list of local heroes includes Mark, spelled right. Mark has not been so moved since the soup.","heroes":["h18"],"parties":[],"loc":"carrbridge"},{"id":"e101","day":4,"season":1,"sday":4,"kind":"town","imp":2,"text":"Varun spends the afternoon searching Ironhaven for a lost little boy, finds him asleep in a hay cart, and carries him home without waking him.","heroes":["h3"],"parties":[],"loc":"ironhaven"},{"id":"e102","day":4,"season":1,"sday":4,"kind":"party_join","imp":3,"text":"First crew for Ankit: Ankit joins The Azure Stallions over drinks in Ironhaven. That makes 3.","heroes":["h14","h3","h12"],"parties":["p5"],"loc":"ironhaven"},{"id":"e103","day":4,"season":1,"sday":4,"kind":"arm_wrestle","imp":2,"text":"Kev and Robert arm-wrestle to a dead heat at The Gilded Flagon. The table does not survive.","heroes":["h2","h7"],"parties":[],"loc":"ironhaven"},{"id":"e104","day":4,"season":1,"sday":4,"kind":"meet","imp":2,"text":"The Cobalt Storm and The Royal Vigil share a fire in the Greenwood. Nobody draws steel, which counts as a good meeting these days.","heroes":["h17","h4","h10","h16"],"parties":["p4","p3"],"loc":"greenwood"},{"id":"e105","day":4,"season":1,"sday":4,"kind":"companion","imp":2,"text":"Ryan and Hilde, a beekeeper carrying a hive on her back, share a fire on the road to Ironhaven, and in the morning simply keep walking together.","heroes":["h15"],"parties":[],"loc":"frosthold"},{"id":"e107","day":4,"season":1,"sday":4,"kind":"talent","imp":2,"text":"Christian beats a dent out of Echo's helmet on a flat rock. It fits better than it did new.","heroes":["h19","h6"],"parties":["p2"],"loc":"goblin_camp"},{"id":"e109","day":4,"season":1,"sday":4,"kind":"pet","imp":2,"text":"Garrett slips Pepper a scrap from supper. Pepper will now follow Garrett to the ends of the realm. Chloe has noticed.","heroes":["h17","h4"],"parties":[],"loc":"greenwood"}],"5":[{"id":"e112","day":5,"season":1,"sday":5,"kind":"bounty_head","imp":3,"text":"Bandits along the King's Road are passing round a sketch of Garrett. The likeness is poor; the reward is not.","heroes":["h4"],"parties":[]},{"id":"e113","day":5,"season":1,"sday":5,"kind":"bounty_head","imp":3,"text":"Word on the road: somebody has put a price on Spencer's head. Being near the top of the table has its costs.","heroes":["h8"],"parties":[]},{"id":"e116","day":5,"season":1,"sday":5,"kind":"fight","imp":2,"text":"The Cobalt Storm dispatches 2 Dire Wolves and a Wolf in the Greenwood. Loot: 7 pelts.","heroes":["h17","h4"],"parties":["p4"],"loc":"greenwood"},{"id":"e117","day":5,"season":1,"sday":5,"kind":"night","imp":2,"text":"Robert follows strange lights away from the camp on the road to Thornwall and comes back at dawn with a trinket and no explanation.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"ironhaven"},{"id":"e118","day":5,"season":1,"sday":5,"kind":"keepsake","imp":3,"text":"The old map was right. Natasha stands at the mouth of Goblin Camp, the map in one hand, and every turn of it matches.","heroes":["h11","h6","h19"],"parties":["p2"],"loc":"goblin_camp"},{"id":"e120","day":5,"season":1,"sday":5,"kind":"fight","imp":3,"text":"First blood for Echo, Natasha and Christian: The Verdant Sigil makes short work of 4 Goblins and a Giant Rat on floor 1 of Goblin Camp. Loot: 6 goblin ears.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp"},{"id":"e121","day":5,"season":1,"sday":5,"kind":"night","imp":2,"text":"A hooded stranger shares The Verdant Sigil's fire in Goblin Camp, eats half the stew, and says something very specific about Emberdeep before leaving.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp"},{"id":"e122","day":5,"season":1,"sday":5,"kind":"boss_race","imp":3,"text":"Two crews, one boss. Copper Whiskers and The Royal Vigil have both set out for the Wolf Den. The taverns are taking bets.","heroes":["h13","h9","h7","h5","h10","h16"],"parties":["p1","p3"],"loc":"wolf_den"},{"id":"e123","day":5,"season":1,"sday":5,"kind":"party_join","imp":3,"text":"First crew for Mark: Mark joins The Azure Stallions over drinks in Ironhaven. That makes 4.","heroes":["h18","h3","h12","h14"],"parties":["p5"],"loc":"ironhaven"},{"id":"e124","day":5,"season":1,"sday":5,"kind":"companion","imp":2,"text":"On the road, Hilde passes on a rumour about Thornmere Ruins that Ryan hasn't heard. It might even be true.","heroes":["h15"],"parties":[],"loc":"frosthold"},{"id":"e125","day":5,"season":1,"sday":5,"kind":"companion","imp":2,"text":"Ines tells Kev the long story of how a mapmaker who keeps getting lost ends up on a road like this. Kev tells the short version of his own.","heroes":["h2"],"parties":[],"loc":"ironhaven"},{"id":"e126","day":5,"season":1,"sday":5,"kind":"companion","imp":2,"text":"At a ford, Ines has somewhere else to be. Kev waves until Ines is out of sight, which is longer than Kev expected to.","heroes":["h2"],"parties":[],"loc":"ironhaven"},{"id":"e127","day":5,"season":1,"sday":5,"kind":"companion","imp":2,"text":"Teodor goes one way at a ford and Spencer the other. There are worse ways to spend a few days than in that company.","heroes":["h8"],"parties":[],"loc":"frosthold"}],"6":[{"id":"e136","day":6,"season":1,"sday":6,"kind":"cooking","imp":2,"text":"Varun eats a Forge-Bellows Pepper Pot at the Ironhaven feast-day tables, elbow to elbow with the whole town. It has a ladle that has never been to the bottom. (8 copper)","heroes":["h3"],"parties":[],"loc":"ironhaven"},{"id":"e137","day":6,"season":1,"sday":6,"kind":"ambush","imp":3,"text":"First blood for Varun, Matt McF, Ankit and Mark: The Azure Stallions dispatch a Bandit Archer, a Bandit and a Bandit Captain at their camp on the King's Road, in the dead of night. Varun kept a cool head; Mark was thinking about the Collapsed Mine the whole fight. Loot: 7 stolen goods, 1 ration.","heroes":["h3","h12","h14","h18"],"parties":["p5"],"loc":"kingsroad"},{"id":"e139","day":6,"season":1,"sday":6,"kind":"fight","imp":2,"text":"The Royal Vigil makes short work of 2 Dire Wolves and 2 Wolves on floor 1 of the Wolf Den. Mikolaj accounted for 3 of them. Loot: 6 pelts, 6 fangs & claws, 8 wolf haunches.","heroes":["h10","h16"],"parties":["p3"],"loc":"wolf_den"},{"id":"e140","day":6,"season":1,"sday":6,"kind":"ambush","imp":3,"text":"Wolves at the Wolf Den, in the middle of the night: The Royal Vigil sees off 2 of them at their camp. Yomna did more than her share and started none of the trouble. Loot: 2 pelts, 2 fangs & claws, 2 wolf haunches.","heroes":["h10","h16"],"parties":["p3"],"loc":"wolf_den"},{"id":"e142","day":6,"season":1,"sday":6,"kind":"contract","imp":2,"text":"Ryan hands over a sealed chest that must not be opened in Ironhaven. Nobody asks. Ryan is paid 74 silver by a man who was never here.","heroes":["h15"],"parties":[],"loc":"ironhaven"},{"id":"e143","day":6,"season":1,"sday":6,"kind":"reading","imp":2,"text":"At a study at the Academy, Magister Quillon reads for Ryan for the first time: the Seven of Cups, among others, and a long look over the top of them.","heroes":["h15"],"parties":[],"loc":"ironhaven"},{"id":"e145","day":6,"season":1,"sday":6,"kind":"reading","imp":3,"text":"Mostly to see what the fuss is about, Kev sits down with Widow Cinder at a cottage at the pithead for a first reading. The Fool upside down comes up, and the fuss makes more sense.","heroes":["h2"],"parties":[],"loc":"veldrock"},{"id":"e146","day":6,"season":1,"sday":6,"kind":"cooking","imp":2,"text":"Mother Grall has written Grey Bread with Dripping on the board at The Pickaxe & Pint in letters a foot high: dish of the week. Kev orders it before sitting down. It is heavy enough to stop a door and good enough to stop a bad day. (4 copper)","heroes":["h2"],"parties":[],"loc":"veldrock"},{"id":"e149","day":6,"season":1,"sday":6,"kind":"town","imp":2,"text":"Garrett spends the afternoon searching Thornwall for a lost little boy, finds him asleep in a hay cart, and carries him home without waking him.","heroes":["h4"],"parties":[],"loc":"thornwall"},{"id":"e150","day":6,"season":1,"sday":6,"kind":"meet","imp":2,"text":"The Azure Stallions and Sam share a fire on the King's Road and trade news.","heroes":["h3","h12","h14","h18","h1"],"parties":["p5"],"loc":"kingsroad"},{"id":"e151","day":6,"season":1,"sday":6,"kind":"talent","imp":2,"text":"Yomna talks for an hour about a brother back home. Mikolaj just listens, which turns out to be the whole job.","heroes":["h16","h10"],"parties":["p3"],"loc":"wolf_den"}],"7":[{"id":"e155","day":7,"season":1,"sday":7,"kind":"fight","imp":3,"text":"On the King's Road, Sam is routed by a Bandit and a Bandit Captain and runs for it. Injured: Sam (sprained ankle).","heroes":["h1"],"parties":[],"loc":"kingsroad"},{"id":"e156","day":7,"season":1,"sday":7,"kind":"rescue","imp":4,"text":"RESCUE on the King's Road: Varun finds Sam bleeding in the road and does not walk past. 2 potions later, Sam is breathing properly.","heroes":["h3","h1","h12","h14","h18"],"parties":["p5"],"loc":"kingsroad"},{"id":"e157","day":7,"season":1,"sday":7,"kind":"vow","imp":3,"text":"Sam owes The Azure Stallions a life, and swears to repay The Azure Stallions. \"A debt is a debt, and I'm paying it with interest!\" says Sam.","heroes":["h1"],"parties":[],"cause":"e156"},{"id":"e159","day":7,"season":1,"sday":7,"kind":"ambush","imp":2,"text":"Spencer makes short work of the Bounty Hunters' Captain and Bounty Hunter on the road to Ironhaven, sent for the price on Spencer's head. Loot: 5 stolen goods, 2 rations.","heroes":["h8"],"parties":[],"loc":"kingsroad"},{"id":"e160","day":7,"season":1,"sday":7,"kind":"reading","imp":2,"text":"A first reading for Spencer at the Academy library. Magister Quillon turns the Moon, raises an eyebrow, and asks if Spencer has been sleeping well.","heroes":["h8"],"parties":[],"loc":"ironhaven"},{"id":"e161","day":7,"season":1,"sday":7,"kind":"treasure","imp":3,"text":"First treasure for Yomna and Mikolaj: behind a hollow under the roots where the cubs were kept on floor 1 of the Wolf Den, nobody had been in years. Yomna comes out with 122 silver and a gem.","heroes":["h10","h16"],"parties":["p3"],"loc":"wolf_den"},{"id":"e162","day":7,"season":1,"sday":7,"kind":"reading","imp":2,"text":"Aunt Crumb lays out Garrett's first spread at the back of the pie shop. \"The Eight of Cups,\" Aunt Crumb says, and lets it sit there.","heroes":["h4"],"parties":[],"loc":"thornwall"},{"id":"e163","day":7,"season":1,"sday":7,"kind":"fight","imp":2,"text":"The Azure Stallions make short work of 2 Bandits and 2 Bandit Captains on the King's Road. Loot: 10 stolen goods, 6 bandit sausages, 4 rations.","heroes":["h3","h12","h14","h18"],"parties":["p5"],"loc":"kingsroad"},{"id":"e164","day":7,"season":1,"sday":7,"kind":"mount","imp":3,"text":"Claire sells Barley, a riding horse, in Thornwall for 30 silver, and doesn't look back. Much.","heroes":["h9"],"parties":[],"loc":"thornwall"},{"id":"e166","day":7,"season":1,"sday":7,"kind":"boss_race","imp":3,"text":"A race for The Silk Matriarch: Kev and Ryan are both bound for the Collapsed Mine. Only one of them gets the kill.","heroes":["h2","h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e168","day":7,"season":1,"sday":7,"kind":"talent","imp":2,"text":"Spencer swallows a torch at the Ironhaven tavern and breathes it out in the shape of a dragon. The house pays.","heroes":["h8"],"parties":[],"loc":"ironhaven"},{"id":"e169","day":7,"season":1,"sday":7,"kind":"companion","imp":2,"text":"Hilde insists on feeding Ryan, on the grounds that heroes never eat properly. It's true.","heroes":["h15"],"parties":[],"loc":"ironhaven"},{"id":"e171","day":7,"season":1,"sday":7,"kind":"keepsake","imp":2,"text":"Robert sleeps with Goodnight within reach. Old habits, old staff.","heroes":["h7"],"parties":[],"loc":"greenwood"},{"id":"e172","day":7,"season":1,"sday":7,"kind":"pet","imp":3,"text":"All evening, Waffles sits between Yomna and Mikolaj, facing Mikolaj, unblinking.","heroes":["h10","h16"],"parties":[],"loc":"wolf_den"},{"id":"e173","day":7,"season":1,"sday":7,"kind":"keepsake","imp":2,"text":"Ankit unfolds the old map of the Collapsed Mine again by the fire. Nobody else can read it. Ankit can, nearly.","heroes":["h14"],"parties":[],"loc":"kingsroad"},{"id":"e175","day":7,"season":1,"sday":7,"kind":"epithet","imp":3,"text":"It sticks: Varun Steady-Hand. Varun pretends to hate it.","heroes":["h3"],"parties":[]}],"8":[{"id":"e177","day":8,"season":1,"sday":8,"kind":"fame","imp":3,"text":"Ironhaven has a new celebrity: a very determined goat, named after Ankit. Ankit pretends to be embarrassed.","heroes":["h14"],"parties":[],"loc":"ironhaven"},{"id":"e178","day":8,"season":1,"sday":8,"kind":"ambush","imp":3,"text":"Copper Whiskers see off 4 Wolves on the road to the Wolf Den, and the last one bolts. Griffin's Hold the Line came at the right time for all of them; Veronika and Clementine the cat found the way out together. Loot: 3 fangs & claws, 2 wolf haunches, 2 pelts.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"greenwood"},{"id":"e180","day":8,"season":1,"sday":8,"kind":"ambush","imp":2,"text":"The Cobalt Storm handles 2 Bounty Hunters and the Bounty Hunters' Captain on the road out of Carrbridge, sent for the price on Garrett's head. The fight turned on Chloe's Volley. Chloe pulled a friend out of trouble and went back in for more. Loot: 5 stolen goods, 1 gem, 4 bandit sausages.","heroes":["h17","h4"],"parties":["p4"],"loc":"kingsroad"},{"id":"e182","day":8,"season":1,"sday":8,"kind":"treasure","imp":3,"text":"First treasure for Natasha, Echo and Christian: on floor 2 of Goblin Camp, a dead adventurer leaves 66 silver and an unidentified relic, which goes to Christian.","heroes":["h11","h6","h19"],"parties":["p2"],"loc":"goblin_camp"},{"id":"e184","day":8,"season":1,"sday":8,"kind":"fight","imp":3,"text":"First blood for Kev, who sees off 2 Giant Bats on floor 1 of the Collapsed Mine. Loot: 1 fang and a pair of bat wings.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"},{"id":"e185","day":8,"season":1,"sday":8,"kind":"fortune","imp":2,"text":"A street palmist in Ironhaven grabs Sam's hand and announces that she will lose something small and find something large. Sam pays 3 copper to make her stop.","heroes":["h1"],"parties":[],"loc":"ironhaven"},{"id":"e186","day":8,"season":1,"sday":8,"kind":"fight","imp":2,"text":"The Azure Stallions handle 3 Bandits, a Bandit Archer and a Bandit Captain on the King's Road. Varun's Volley fell on four of them like hail. Loot: 7 stolen goods, 4 bandit sausages, 2 rations.","heroes":["h3","h12","h14","h18"],"parties":["p5"],"loc":"kingsroad"},{"id":"e187","day":8,"season":1,"sday":8,"kind":"trait","imp":3,"text":"After nearly dying on the King's Road, Matt McF is more careful now (risk tolerance: prudent → careful).","heroes":["h12"],"parties":[]},{"id":"e188","day":8,"season":1,"sday":8,"kind":"fight","imp":3,"text":"The Azure Stallions scrape past 3 Bandit Captains, a Bandit and a Bandit Archer on the King's Road, though Matt McF goes down with a sprained ankle. Varun's Hunter's Mark finished it, and Matt McF's Turn Undead caught three at once. Loot: 15 stolen goods.","heroes":["h3","h12","h14","h18"],"parties":["p5"],"loc":"kingsroad"},{"id":"e189","day":8,"season":1,"sday":8,"kind":"fishing","imp":2,"text":"The books show no Silver Roach until today, when Ankit lands one at the King's Road ford.","heroes":["h14"],"parties":[],"loc":"kingsroad"},{"id":"e191","day":8,"season":1,"sday":8,"kind":"vow","imp":2,"text":"Sam brings an unfinished vow into Sam's Pack: to repay The Azure Stallions, and the pack takes it on. \"A debt's a debt,\" says Spencer, \"and we'll pay it together.\"","heroes":["h1"],"parties":["p6"]},{"id":"e192","day":8,"season":1,"sday":8,"kind":"party_formed","imp":4,"text":"Sam and Spencer shake on it at The Gilded Flagon: they are now Sam's Pack, honorable by the look of them.","heroes":["h1","h8"],"parties":["p6"],"loc":"ironhaven"},{"id":"e194","day":8,"season":1,"sday":8,"kind":"companion","imp":2,"text":"The road forks at Veldrock and so do Ryan and Hilde. It was a good few days.","heroes":["h15"],"parties":[],"loc":"veldrock"},{"id":"e196","day":8,"season":1,"sday":8,"kind":"cooking","imp":2,"text":"Kev's Devilled Bat Wings go wrong in the Collapsed Mine. There's nobody to say so, but the smell says it for them.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"},{"id":"e197","day":8,"season":1,"sday":8,"kind":"talent","imp":2,"text":"Griffin says a quiet grace over the fire. Claire bows too, a beat late.","heroes":["h5","h9"],"parties":["p1"],"loc":"wolf_den"},{"id":"e198","day":8,"season":1,"sday":8,"kind":"talent","imp":2,"text":"Christian takes Echo's turn on watch without being asked, and doesn't mention it in the morning.","heroes":["h19","h6"],"parties":["p2"],"loc":"goblin_camp"},{"id":"e199","day":8,"season":1,"sday":8,"kind":"talent","imp":2,"text":"Ankit carries Mark's pack the last mile back to camp and says it was no trouble. It was some trouble.","heroes":["h14","h18"],"parties":["p5"],"loc":"kingsroad"},{"id":"e200","day":8,"season":1,"sday":8,"kind":"campfire","imp":2,"text":"Sam catches Spencer humming and doesn't say anything. That's a start.","heroes":["h8","h1"],"parties":["p6"],"loc":"ironhaven"},{"id":"e201","day":8,"season":1,"sday":8,"kind":"dream","imp":2,"text":"If you've shared a fire with Echo, you know the plan: to have three true friends. The friendships are still forming.","heroes":["h6"],"parties":[]}],"9":[{"id":"e203","day":9,"season":1,"sday":9,"kind":"underdog","imp":3,"text":"Griffin woke up 19th of 19 this season, but the table doesn't tell you about day 8 of season 1, when Copper Whiskers saw off 4 Wolves on the road to the Wolf Den. Seasons turn.","heroes":["h5"],"parties":[]},{"id":"e207","day":9,"season":1,"sday":9,"kind":"fight","imp":2,"text":"Copper Whiskers cut down 4 Wolves on floor 1 of the Wolf Den. The wolf had been trouble right up until Veronika's Hunter's Mark. Griffin kept everyone standing (3 healed). Loot: 3 pelts, 3 fangs & claws, a wolf haunch.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e208","day":9,"season":1,"sday":9,"kind":"ambush","imp":3,"text":"In the middle of the night at their camp in the Wolf Den, Copper Whiskers make short work of 2 Dire Wolves and a Wolf. Veronika drew, held and let Hunter's Mark go, and the dire wolf never saw it; Robert found the weak spot first and kept hitting it. Loot: 4 pelts, 4 fangs & claws, 2 wolf haunches.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e210","day":9,"season":1,"sday":9,"kind":"boss","imp":5,"text":"Down at the bottom of Goblin Camp, The Verdant Sigil slays Gruk the Warchief, a Goblin Archer and a Goblin. Echo's Pinning Shot dropped Gruk, Christian's Hammer Down tied him up, and Echo did the unglamorous work that kept the line from breaking. Loot: 6 goblin ears, 3 trinkets, Gruk's own smoked ham.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp"},{"id":"e212","day":9,"season":1,"sday":9,"kind":"night","imp":2,"text":"Echo's ghost story in Goblin Camp ends with \"...and it was standing right behind them.\" Natasha does not look behind her once, all night.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp"},{"id":"e214","day":9,"season":1,"sday":9,"kind":"bodies","imp":2,"text":"Kev wraps what's left of the kobold slinger in an old blanket and ties it to his pack. The crows watch with professional interest.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"},{"id":"e219","day":9,"season":1,"sday":9,"kind":"boss_race","imp":2,"text":"The race for Old Grizzlemaw is one crew lighter: The Royal Vigil turned for other work. That leaves Copper Whiskers.","heroes":["h10","h16"],"parties":["p3"],"loc":"wolf_den"},{"id":"e220","day":9,"season":1,"sday":9,"kind":"omen_true","imp":3,"text":"Three days ago Magister Quillon turned the Page of Swords for Ryan. Ryan has kept watch through 3 days of road since, and nothing crept up.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e221","day":9,"season":1,"sday":9,"kind":"night_game","imp":3,"text":"A first game of checkers at camp in the Ashveil Crypts: Chloe beats Garrett, and the record begins.","heroes":["h17","h4"],"parties":[],"loc":"ashveil_crypts"},{"id":"e222","day":9,"season":1,"sday":9,"kind":"argument","imp":3,"text":"Whose idea was the last dungeon? Christian and Natasha of The Verdant Sigil settle it with a shouting match.","heroes":["h19","h11"],"parties":["p2"]},{"id":"e223","day":9,"season":1,"sday":9,"kind":"argument","imp":3,"text":"It starts with whose idea the last dungeon was, and it ends with Yomna and Mikolaj sleeping on opposite sides of the fire.","heroes":["h10","h16"],"parties":["p3"]},{"id":"e224","day":9,"season":1,"sday":9,"kind":"pet","imp":2,"text":"Millie decides Spencer is acceptable and settles down beside Spencer at the camp. Sam feels oddly proud.","heroes":["h1","h8"],"parties":[],"loc":"kingsroad"},{"id":"e225","day":9,"season":1,"sday":9,"kind":"dream","imp":2,"text":"Griffin mentions it again tonight: to be the most famous hero in the league. Nobody laughs. Not any more.","heroes":["h5"],"parties":[]},{"id":"e226","day":9,"season":1,"sday":9,"kind":"dream","imp":2,"text":"Ask Christian where all this ends and the answer hasn't changed: to slay the dragon of Emberdeep.","heroes":["h19"],"parties":[]},{"id":"e228","day":9,"season":1,"sday":9,"kind":"big_move","imp":4,"text":"Gruk the Warchief is down, and the table moves: Echo +56 renown (11th to 2nd), Christian +52 (10th to 3rd) and Natasha +51 (12th to 4th). The Verdant Sigil +107 party renown, 3rd to 1st among the crews.","heroes":["h6","h19","h11"],"parties":["p2"],"cause":"e210"}],"10":[{"id":"e229","day":10,"season":1,"sday":9,"kind":"rework","imp":3,"text":"The old tunnels have shifted, say the guild halls: every lair has new rooms and new tenants, and every map drawn before today is waste paper. Every hero gets a torch, and the 13 who held old maps get bought out.","heroes":["h2","h4","h5","h6","h7","h9","h10","h11","h13","h14","h16","h18","h19"],"parties":[]},{"id":"e230","day":10,"season":1,"sday":10,"kind":"weather","imp":2,"text":"It rains on the east all day. Ryan insists it is good for the crops, to no one in particular.","heroes":["h15"],"parties":[],"loc":"saltmarrow"},{"id":"e231","day":10,"season":1,"sday":10,"kind":"legend","imp":4,"text":"In the Collapsed Mine, Sable Vey, the Wandering Star, stops Kev and says, very quietly: \"Cragtooth Warren. Go soon.\" Then Sable Vey is simply not there.","heroes":["h2"],"parties":[],"loc":"collapsed_mine","legend":"Sable Vey"},{"id":"e233","day":10,"season":1,"sday":10,"kind":"keepsake","imp":3,"text":"Garrett unfolds his old map at the mouth of the Ashveil Crypts. The tunnels have moved since it was drawn, and not one turn of it matches. He folds it away anyway: it got him here.","heroes":["h4","h17"],"parties":["p4"],"loc":"ashveil_crypts"},{"id":"e238","day":10,"season":1,"sday":10,"kind":"trap","imp":2,"text":"Ryan springs a rotten beam in the adit mouth on the first floor of the Collapsed Mine (concussion).","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e245","day":10,"season":1,"sday":10,"kind":"ambush","imp":2,"text":"With Griffin holding the line, Copper Whiskers beat 3 Dire Wolves at their camp on the first floor of the Wolf Den, in the middle of the night. The last dire wolf turns tail. Veronika put Hunter's Mark on the dire wolf, and everyone's blows followed it. Griffin's Taunt was the quiet reason it went their way. Claire stitched two cuts before anyone had sat down. Loot: 1 pelt, 3 fangs & claws, 3 wolf haunches.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e246","day":10,"season":1,"sday":10,"kind":"wild_room","imp":3,"text":"Kev took a corner in an ore cart in the Collapsed Mine on two wheels, then on none. The corner was unharmed.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"},{"id":"e248","day":10,"season":1,"sday":10,"kind":"gear","imp":2,"text":"Widow Saffery hands Ankit a Runed Staff and pockets 146 silver. Both look pleased.","heroes":["h14"],"parties":[],"loc":"carrbridge"},{"id":"e253","day":10,"season":1,"sday":10,"kind":"boss_race","imp":3,"text":"Someone has chalked a tally on the board for the race to Vessimir the Unburied: The Royal Vigil against The Cobalt Storm. Odds are on offer, mostly on whoever's buying.","heroes":["h10","h16","h17","h4"],"parties":["p3","p4"],"loc":"ashveil_crypts"},{"id":"e254","day":10,"season":1,"sday":10,"kind":"omen_true","imp":2,"text":"Four days ago, Widow Cinder warned Kev of a heavy heart. Kev has had 3 heavy-hearted nights since.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"},{"id":"e255","day":10,"season":1,"sday":10,"kind":"fishing","imp":2,"text":"Nobody in the league has landed a brown trout before, and now Sam has, at the King's Road ford. A first.","heroes":["h1"],"parties":[],"loc":"kingsroad"},{"id":"e258","day":10,"season":1,"sday":10,"kind":"campfire","imp":3,"text":"Robert and Veronika find out they grew up three valleys apart, and the conversation runs a lot longer than either of them expected.","heroes":["h7","h13"],"parties":["p1"],"loc":"wolf_den"},{"id":"e261","day":10,"season":1,"sday":10,"kind":"dream","imp":2,"text":"Garrett still means to finish a season among the three most famous heroes in the league. One day. Not today.","heroes":["h4"],"parties":[]},{"id":"e262","day":10,"season":1,"sday":10,"kind":"dream","imp":2,"text":"Mark still means to set foot in six of the realm's towns. 3 towns down; 6 is the mark.","heroes":["h18"],"parties":[]},{"id":"e264","day":10,"season":1,"sday":10,"kind":"aside","imp":3,"text":"Mikolaj sits alone in Hollowood with something red and expensive, and a long look out of the window.","heroes":["h16"],"parties":[],"loc":"hollowood"},{"id":"e265","day":10,"season":1,"sday":10,"kind":"bodies_end","imp":2,"text":"Kev's pack is too heavy, and what's left of the kobold slinger is the first thing to go. Kev leaves it in a side passage, roughly covered with loose stones.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"}],"11":[{"id":"e267","day":11,"season":1,"sday":11,"kind":"road","imp":3,"text":"'Oyez!' cries Jory Bellwether, and tells the whole road a piece of news about the Collapsed Mine that Mark very much wanted to hear.","heroes":["h18","h12","h14","h3"],"parties":["p5"]},{"id":"e269","day":11,"season":1,"sday":11,"kind":"fight","imp":2,"text":"In the whelping hollow on the first floor of the Wolf Den, Copper Whiskers see off 4 Dire Wolves and a Wolf. Taunt from Griffin kept the back row out of it. Robert took the worst corner of the fight and kept it. Loot: 12 fangs & claws, 6 pelts, 4 wolf haunches.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e271","day":11,"season":1,"sday":11,"kind":"talent","imp":2,"text":"Robert knocks a pine cone off a branch in the dark, by sound alone. Veronika demands to see it again. The trick has a name: Trick Shot.","heroes":["h7","h13"],"parties":["p1"],"loc":"wolf_den"},{"id":"e272","day":11,"season":1,"sday":11,"kind":"night","imp":2,"text":"Somewhere in Griffin's ghost story on the first floor of the Wolf Den, Robert stops pretending not to listen.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e276","day":11,"season":1,"sday":11,"kind":"fishing","imp":2,"text":"Sam catches a pike at the King's Road ford, the league's very first, and the bank applauds like it was planned.","heroes":["h1"],"parties":[],"loc":"kingsroad"},{"id":"e277","day":11,"season":1,"sday":11,"kind":"fight","imp":3,"text":"Ryan's first blood comes in the pithead on the first floor of the Collapsed Mine: a Giant Bat and a Giant Rat, handled. Loot: a pair of bat wings, 1 fang.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e281","day":11,"season":1,"sday":11,"kind":"road","imp":3,"text":"On the road to Thornwall, a torn treasure map blows across the path and wraps around Natasha's ankle. It is faded, but Emberdeep is clearly marked.","heroes":["h11","h19","h6"],"parties":["p2"]},{"id":"e282","day":11,"season":1,"sday":11,"kind":"relic","imp":3,"text":"The temple in Thornwall knows old things: Christian's relic is the Circlet of the Clear Head (sharper, more charming). Christian settles an argument about the cooking rota in one sentence, the circlet cool on his brow.","heroes":["h19"],"parties":[],"loc":"thornwall"},{"id":"e283","day":11,"season":1,"sday":11,"kind":"bond","imp":2,"text":"Echo and Christian have been seen laughing at The Sagging Beam until the barkeep asked them to stop. Friends, apparently.","heroes":["h6","h19"],"parties":[],"loc":"thornwall","bond":"friends"},{"id":"e284","day":11,"season":1,"sday":11,"kind":"omen_true","imp":2,"text":"Five days ago, Aunt Crumb warned Robert of restless nights. Robert has lain awake 3 nights since.","heroes":["h7"],"parties":[],"loc":"wolf_den"},{"id":"e287","day":11,"season":1,"sday":11,"kind":"fishing","imp":2,"text":"Kev adds a new name to the league's catch book at the flooded gallery of the Collapsed Mine: Blind Cavefish, 10 cm, never taken before.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"},{"id":"e290","day":11,"season":1,"sday":11,"kind":"bond","imp":2,"text":"Garrett saves Chloe the dry side of the fire these days. That's friendship, out here.","heroes":["h17","h4"],"parties":[],"loc":"ashveil_crypts","bond":"friends"},{"id":"e291","day":11,"season":1,"sday":11,"kind":"campfire","imp":2,"text":"Chloe and Garrett have the same terrible sense of humour, and anyone in earshot is suffering.","heroes":["h17","h4"],"parties":["p4"],"loc":"ashveil_crypts"},{"id":"e292","day":11,"season":1,"sday":11,"kind":"dream","imp":2,"text":"A fortune teller asks Varun what Varun wants. Easy: to set foot in six of the realm's towns. The count stands at 3 of 6 towns.","heroes":["h3"],"parties":[]},{"id":"e294","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"Copper Whiskers set their sights for the season: to bring down The Silk Matriarch in the Collapsed Mine. \"Spiders. Fine. Someone else holds the torch,\" says Veronika.","heroes":["h13","h9","h7"],"parties":["p1"]},{"id":"e295","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Verdant Sigil settles on a goal: to earn 1,150 silver between them before the season ends. \"Eleven hundred and fifty! We're going to need a bigger purse!\" says Natasha.","heroes":["h6","h11","h19"],"parties":["p2"]},{"id":"e296","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"The Royal Vigil sets their sights for the season: to find a relic of the old world. \"Something out there hasn't been touched in a thousand years, and we're going to be the ones who touch it,\" says Yomna.","heroes":["h10","h16"],"parties":["p3"]},{"id":"e297","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"The Cobalt Storm's plan for the season, as told to the barkeep: to see the world, 6 different places before the season ends. \"Six places. We'll write every one of them down,\" says Garrett.","heroes":["h17","h4"],"parties":["p4"]},{"id":"e298","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"The Azure Stallions set their sights for the season: to light a candle at the drowned shrine in Ashfen. \"Drowned shrine? How drowned, exactly?\" asks Ankit.","heroes":["h3","h12","h14"],"parties":["p5"]},{"id":"e299","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, Sam's Pack settles on a goal: to finish the season as one of the top three parties. \"Top three, and we'll wave at everyone on the way up!\" says Sam.","heroes":["h1","h8"],"parties":["p6"]},{"id":"e300","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"Kev sets his sights for the season: to earn 100 silver before the season ends. \"A hundred silver. Don't expect me to share,\" says Kev.","heroes":["h2"],"parties":[]},{"id":"e301","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"Ryan sets his sights for the season: to look the sea in the eye at Saltmarrow. \"Just look at it. From a sensible distance,\" says Ryan.","heroes":["h15"],"parties":[]}],"12":[{"id":"e306","day":12,"season":1,"sday":12,"kind":"legend","imp":4,"text":"In the Collapsed Mine, Brother Toad, Keeper of the Long Road, stops Ryan and says, very quietly, \"The Ashveil Crypts. Go soon.\" Then Brother Toad is simply not there.","heroes":["h15"],"parties":[],"loc":"collapsed_mine","legend":"Brother Toad"},{"id":"e311","day":12,"season":1,"sday":12,"kind":"trap","imp":2,"text":"Varun springs a rotten beam in the first run on the first floor of Cragtooth Warren (sprained ankle) (Matt McF hurt too).","heroes":["h3","h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e312","day":12,"season":1,"sday":12,"kind":"fight","imp":2,"text":"With Mark hitting hardest, the Azure Stallions make short work of 3 Kobolds and a Giant Bat in the bat roost on the first floor of Cragtooth Warren. One more Hunter's Mark from Mark, and the kobold was down for good. Varun read the fight like a page of large print. Loot: 5 silver each, a pair of bat wings, 3 kobold firepeppers.","heroes":["h3","h12","h14","h18"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e313","day":12,"season":1,"sday":12,"kind":"fight","imp":2,"text":"The Azure Stallions see off 3 Kobold Slingers and 2 Goblin Archers in the slingers' gallery on the first floor of Cragtooth Warren. The fight ended in a flash of Matt McF's Smite. Loot: 9 silver each, 3 goblin ears, 4 ore.","heroes":["h3","h12","h14","h18"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e314","day":12,"season":1,"sday":12,"kind":"wild_room","imp":3,"text":"Mark has cleaned out the knucklebones circle in Cragtooth Warren, and the kobolds are now checking their bones for weights.","heroes":["h3","h12","h14","h18"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e316","day":12,"season":1,"sday":12,"kind":"talent","imp":2,"text":"Matt McF says a quiet grace over the fire. Varun bows too, a beat late.","heroes":["h12","h3"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e317","day":12,"season":1,"sday":12,"kind":"wild_room","imp":3,"text":"The button in the Wolf Den said DO NOT PRESS. Robert pressed it, and has the bucket to show for it.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e320","day":12,"season":1,"sday":12,"kind":"famous_trap","imp":3,"text":"The Widow's Shaft in the Collapsed Mine has caught its first since the new tenant moved in, and it's Kev.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"},{"id":"e324","day":12,"season":1,"sday":12,"kind":"town","imp":2,"text":"A stranger in Carrbridge sells Christian a treasure map for 14 silver. It points to Frostspire, and it might even be real.","heroes":["h19"],"parties":[],"loc":"carrbridge"},{"id":"e325","day":12,"season":1,"sday":12,"kind":"mood","imp":2,"text":"Kev chalks every turn on the wall, even the ones already on the map.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"},{"id":"e326","day":12,"season":1,"sday":12,"kind":"meet","imp":2,"text":"Everyone agrees the weather is against them all: The Royal Vigil and The Cobalt Storm stop outside the Ashveil Crypts just long enough to say so, and part on good terms.","heroes":["h10","h16","h17","h4"],"parties":["p3","p4"],"loc":"ashveil_crypts"},{"id":"e328","day":12,"season":1,"sday":12,"kind":"omen_true","imp":2,"text":"Aunt Crumb turned the Five of Swords for Garrett five days ago and went quiet. Garrett has had sharp words with Chloe since, over nothing much.","heroes":["h4"],"parties":[],"loc":"ashveil_crypts"},{"id":"e331","day":12,"season":1,"sday":12,"kind":"fishing","imp":2,"text":"A first for the whole league: Kev pulls a deep gulper at the flooded gallery of the Collapsed Mine and holds it up as proof.","heroes":["h2"],"parties":[],"loc":"collapsed_mine"},{"id":"e332","day":12,"season":1,"sday":12,"kind":"dream","imp":2,"text":"Kev carries the dream like a stone in a pocket: to own a treasure with a name of its own. Heavier some days than others.","heroes":["h2"],"parties":[]},{"id":"e333","day":12,"season":1,"sday":12,"kind":"dream","imp":2,"text":"Every tavern Mikolaj sits in, the same dream comes up: to own a treasure with a name of its own. The others have heard it before.","heroes":["h16"],"parties":[]}],"13":[{"id":"e337","day":13,"season":1,"sday":13,"kind":"cooking","imp":2,"text":"Feast day in Carrbridge: the cook has made Stolen-Sausage Hotpot from the parts heroes sold here this season, and Echo gets the first bowl. It is all the sweeter for being stolen twice. (8 copper)","heroes":["h6"],"parties":[],"loc":"carrbridge"},{"id":"e338","day":13,"season":1,"sday":13,"kind":"trait","imp":3,"text":"Helping kill 2 Wolves and Old Grizzlemaw has done something for Veronika: she is bolder now (boldness: cautious → steady).","heroes":["h13"],"parties":[]},{"id":"e339","day":13,"season":1,"sday":13,"kind":"relic_found","imp":3,"text":"First relic: Veronika pockets an unidentified relic from the Wolf Den. It hums faintly.","heroes":["h13"],"parties":[],"loc":"wolf_den"},{"id":"e340","day":13,"season":1,"sday":13,"kind":"boss","imp":5,"text":"Two Wolves and Old Grizzlemaw held the bottom of the Wolf Den long enough: Copper Whiskers kill them. Griffin's Intercept took the worst of it, Claire's Smite turned it back, Veronika kept swinging and Bear the dog never left Griffin's side. Loot: 4 pelts, 3 fangs & claws, Grizzlemaw's honeycomb.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e341","day":13,"season":1,"sday":13,"kind":"treasure","imp":3,"text":"First treasure for Veronika, Claire, Robert and Griffin: with Old Grizzlemaw gone, the Wolf Den gives up its best-kept secret, 4 gold pieces and 4 silver in a locked chest.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e342","day":13,"season":1,"sday":13,"kind":"race_won","imp":3,"text":"Copper Whiskers win the race to Old Grizzlemaw, and the bets are paid out in Hollowood before the blood is dry.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e343","day":13,"season":1,"sday":13,"kind":"gear","imp":4,"text":"Griffin comes out of the Wolf Den wearing a heavy coat of grey bear fur from the old bear's winter chamber: one of a kind, and not yet understood.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e345","day":13,"season":1,"sday":13,"kind":"delve_done","imp":3,"text":"After 5 days, Copper Whiskers come out of the Wolf Den with the dark in every seam and their own map of it complete: Old Snapjaw, a walled-up room, a hidden room and 2 more good rooms found, 16 rooms worked, 235 silver between them. Going by everyone's notes, the Wolf Den is 65% explored.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"loc":"wolf_den"},{"id":"e346","day":13,"season":1,"sday":13,"kind":"cooking","imp":3,"text":"Griffin cooks Grizzlemaw Honey Cakes in the Wolf Den and nobody keeps watch, because nothing would dare interrupt. They taste of forty summers.","heroes":["h13","h9","h7","h5"],"parties":[],"loc":"wolf_den"},{"id":"e349","day":13,"season":1,"sday":13,"kind":"evolve","imp":4,"text":"Varun the Ranger becomes a Pathfinder! Campsite Scout and Pathfinding led the way to a career heavy on the wilds and the open road. (Has never once been lost. Claims to have never once been lost.) First new trick: Lay of the Land.","heroes":["h3"],"parties":[],"cls_to":"pathfinder"},{"id":"e350","day":13,"season":1,"sday":13,"kind":"evolve","imp":4,"text":"Matt McF the Warrior becomes a Paladin! Smite and Turn Undead led the way to a career heavy on holy work. (Armored faith with a mace.) First new trick: Radiance.","heroes":["h12"],"parties":[],"cls_to":"paladin"},{"id":"e351","day":13,"season":1,"sday":13,"kind":"evolve","imp":4,"text":"Ankit the Mage becomes a Cleric! Pilgrim and Devout led the way to a career heavy on holy work and healing. (Keeps everyone alive and reminds them of it.) First new trick: Bless, and the guild sends over a Wool Hood to go with it.","heroes":["h14"],"parties":[],"cls_to":"cleric"},{"id":"e352","day":13,"season":1,"sday":13,"kind":"evolve","imp":4,"text":"Mark the Ranger becomes a Trapper! Honed Edge and Smith's Hands led the way to a career heavy on crafting. (Makes the forest bite.) First new trick: Bear Trap, and the guild sends over a Padded Cap to go with it.","heroes":["h18"],"parties":[],"cls_to":"trapper"},{"id":"e357","day":13,"season":1,"sday":13,"kind":"road","imp":3,"text":"On the roadside, Sergeant Hobb Withy puts Spencer through a drill: stand, turn, kneel, rise. Spencer comes out of it standing straighter, and humbled.","heroes":["h8","h1"],"parties":["p6"]},{"id":"e360","day":13,"season":1,"sday":13,"kind":"night","imp":2,"text":"The lights on the first floor of the Collapsed Mine lead Ryan round in circles until dawn. Ryan comes back muddy and in no mood to talk.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e361","day":13,"season":1,"sday":13,"kind":"song","imp":3,"text":"Nobody in Saltmarrow can stop humming \"Nobody Told Varun\", new at The Drowned Gull: the Azure Stallions on the King's Road, and Varun kneeling by Sam with two potions.","heroes":["h3"],"parties":[],"loc":"saltmarrow"},{"id":"e362","day":13,"season":1,"sday":13,"kind":"song","imp":3,"text":"\"Ring the Bells for Matt McF\" is new at The Drowned Gull tonight, about the Azure Stallions getting off the King's Road alive. The bard swears every word is true.","heroes":["h12"],"parties":[],"loc":"saltmarrow"},{"id":"e363","day":13,"season":1,"sday":13,"kind":"song","imp":3,"text":"Also at The Drowned Gull: \"The King's Road Never Saw Ankit Coming\". The tune is borrowed. The words are new.","heroes":["h14"],"parties":[],"loc":"saltmarrow"},{"id":"e364","day":13,"season":1,"sday":13,"kind":"song","imp":3,"text":"At The Watching Oak tonight, \"Mark and the King's Road\" tells of the Azure Stallions getting off the King's Road alive. By the third verse the whole room knows the words.","heroes":["h18"],"parties":[],"loc":"hollowood"},{"id":"e366","day":13,"season":1,"sday":13,"kind":"cooking","imp":2,"text":"Mikolaj lays out some Wolf Stew in the Ashveil Crypts on a flat stone, like a proper table. It keeps everyone warm all night.","heroes":["h10","h16"],"parties":[],"loc":"ashveil_crypts"},{"id":"e367","day":13,"season":1,"sday":13,"kind":"night_game","imp":2,"text":"At camp in the Ashveil Crypts, Chloe beats Garrett at checkers, 3-0 now. Neither of them calls it luck any more.","heroes":["h17","h4"],"parties":[],"loc":"ashveil_crypts"},{"id":"e368","day":13,"season":1,"sday":13,"kind":"fishing","imp":2,"text":"Ryan adds a new name to the league's catch book at the flooded gallery of the Collapsed Mine: Pale Loach, 22 cm, never taken before.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e371","day":13,"season":1,"sday":13,"kind":"dream","imp":2,"text":"Still the plan, says Sam: to make a fortune (2,000 silver earned). 54 of 2,000 silver so far.","heroes":["h1"],"parties":[]},{"id":"e372","day":13,"season":1,"sday":13,"kind":"dream","imp":2,"text":"Ryan hasn't given up on it: to finish a season among the three most famous heroes in the league. The road is long; the dream is longer.","heroes":["h15"],"parties":[]},{"id":"e374","day":13,"season":1,"sday":13,"kind":"epithet","imp":3,"text":"A bard tries out \"Griffin First-Down\" in a verse, and the whole tavern sings it back. That's that, then.","heroes":["h5"],"parties":[]},{"id":"e375","day":13,"season":1,"sday":13,"kind":"epithet","imp":3,"text":"From now on, around the taverns, it's Robert Front-Runner.","heroes":["h7"],"parties":[]},{"id":"e376","day":13,"season":1,"sday":13,"kind":"epithet","imp":3,"text":"Children in the street have started calling Claire \"the Quick\", and the grown-ups are not far behind.","heroes":["h9"],"parties":[]},{"id":"e377","day":13,"season":1,"sday":13,"kind":"big_move","imp":4,"text":"With Two Wolves and Old Grizzlemaw dead at the bottom of the Wolf Den, the crew table shifts: Copper Whiskers +69 party renown, 3rd to 1st among the crews.","heroes":["h13","h9","h7","h5"],"parties":["p1"],"cause":"e340"}],"14":[{"id":"e380","day":14,"season":1,"sday":14,"kind":"weather","imp":2,"text":"It rains on the west all day. Claire insists it is good for the crops, to no one in particular.","heroes":["h9"],"parties":[],"loc":"hollowood"},{"id":"e381","day":14,"season":1,"sday":14,"kind":"tarot","imp":2,"text":"Spencer queues at the Ironhaven omen fair for Magister Quillon, who reads at a trestle under a string of paper moons. Magister Quillon suggests a different day for anything important.","heroes":["h8"],"parties":[],"loc":"ironhaven"},{"id":"e382","day":14,"season":1,"sday":14,"kind":"night","imp":3,"text":"Out of nowhere, a child turns up at Sam's Pack's camp in Redcrag Hills, announces that the Sunken Vault \"eats lanterns\", and is gone before anyone can ask what that means.","heroes":["h1","h8"],"parties":["p6"],"loc":"redcrag"},{"id":"e384","day":14,"season":1,"sday":14,"kind":"relic","imp":3,"text":"The temple in Hollowood knows old things. Veronika's relic is Cloak of Dusk (much harder to hit), and wrapped in it on watch she vanishes entirely, which the party finds unnerving. The same day, Griffin's turns out to be Grizzlemaw's Last Winter Coat.","heroes":["h13","h5"],"parties":[],"loc":"hollowood"},{"id":"e387","day":14,"season":1,"sday":14,"kind":"mount","imp":2,"text":"Claire leaves the Hollowood stables on Bartholomew, a donkey, 10 silver lighter and a head taller.","heroes":["h9"],"parties":[],"loc":"hollowood"},{"id":"e389","day":14,"season":1,"sday":14,"kind":"town","imp":2,"text":"A pickpocket in Hollowood picks the wrong mark. Claire catches the hand mid-pocket and marches the kid to Ranger Holt, who pays 5 silver for the trouble.","heroes":["h9"],"parties":[],"loc":"hollowood"},{"id":"e390","day":14,"season":1,"sday":14,"kind":"town","imp":3,"text":"When a hayloft goes up in Hollowood, Robert hauls water until dawn. Ranger Holt says thanks, which for Ranger Holt is a speech.","heroes":["h7"],"parties":[],"loc":"hollowood"},{"id":"e391","day":14,"season":1,"sday":14,"kind":"trap","imp":2,"text":"Mikolaj springs a coffin lid that falls in the coffin-makers' yard on the first floor of the Ashveil Crypts (bruised ribs).","heroes":["h16"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e397","day":14,"season":1,"sday":14,"kind":"trap","imp":2,"text":"Matt McF springs a pit full of stakes in the testing run on the first floor of Cragtooth Warren (sprained ankle).","heroes":["h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e402","day":14,"season":1,"sday":14,"kind":"omen_true","imp":2,"text":"The Chariot, said Sabine Venn to Varun five days ago. Varun has won 3 fights since without once falling back.","heroes":["h3"],"parties":[],"loc":"cragtooth_warren"},{"id":"e403","day":14,"season":1,"sday":14,"kind":"keepsake","imp":2,"text":"Garrett adds a new corridor to the old map of the Ashveil Crypts in careful ink.","heroes":["h4"],"parties":[],"loc":"ashveil_crypts"},{"id":"e404","day":14,"season":1,"sday":14,"kind":"keepsake","imp":2,"text":"The letter from home is still sealed in Matt McF's coat. Matt McF checks it is there every night.","heroes":["h12"],"parties":[],"loc":"cragtooth_warren"},{"id":"e406","day":14,"season":1,"sday":14,"kind":"dream","imp":2,"text":"Late at night Ankit counts it up again: to set foot in six of the realm's towns. 2 of 6 towns, and counting.","heroes":["h14"],"parties":[]},{"id":"e408","day":14,"season":1,"sday":14,"kind":"ledger","imp":2,"text":"The week's trade: 9 packs emptied onto counters for 788 silver. Biggest haul: Ankit, 326 silver in Carrbridge. Back up from the deep: The Royal Vigil (3 days in the Wolf Den), The Verdant Sigil (6 days in Goblin Camp), Kev (6 days in the Collapsed Mine).","heroes":["h14","h10","h6","h2"],"parties":["p3","p2"]}]};